import {native} from "./approved-api.mjs";
import {installEmailWorkspace,installContextualEmail} from "./email-studio.mjs";
import {canComposePipelineEmail,pipelineEmailContext} from "./pipeline-email.mjs";
export function mount({hostCompanies,hostCandidate,hostJD,candidateShadow,jdShadow,companyShadow,activate}){
const EMAIL_STUDIO_DOCUMENT="<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"color-scheme\" content=\"light\">\n  <title>Jobmitra Email Studio V8 — Auto Recipient Prefill & Editable To</title>\n  <style>\n    :root{--ink:#18232f;--muted:#637181;--stroke:#dfe5eb;--canvas:#f4f6f8;--red:#dd0000;--red-dark:#dd0000;--light-red:#fff6f6;--paper:#fff;--ok:#187146;--shadow:0 14px 45px rgba(26,39,59,.075)}\n    *{box-sizing:border-box}\n    body{margin:0;font-family:Segoe UI,Arial,Helvetica,sans-serif;color:var(--ink);background:var(--canvas);font-size:14px;line-height:1.48}\n    button,input,select,textarea{font:inherit}\n    button{cursor:pointer}\n    .top-accent{height:5px;background:var(--red)}\n    header{background:#fff;border-bottom:1px solid var(--stroke);padding:17px max(22px,calc((100vw - 1450px)/2));display:flex;align-items:center;justify-content:space-between;gap:12px}\n    .brand{display:flex;align-items:center;gap:14px;min-width:0}\n    .brand-logo{height:54px;width:auto;display:block;border-radius:6px;box-shadow:0 5px 14px rgba(20,28,38,.08)}\n    .brand-text{min-width:0}\n    .brand b{font-size:19px;letter-spacing:-.35px;display:block;line-height:1.15}\n    .brand b span{color:var(--red)}\n    .brand small{font-size:11px;letter-spacing:.9px;color:var(--muted);font-weight:650;text-transform:uppercase}\n    .header-right{display:flex;gap:12px;align-items:center;color:var(--muted);font-size:12px}\n    .local-badge{display:inline-flex;align-items:center;gap:7px;border:1px solid #d6e7dc;background:#f0faf4;color:#28784b;font-size:12px;padding:7px 11px;border-radius:100px;font-weight:600}\n    .dot{width:7px;height:7px;background:#229c57;border-radius:50%}\n    .page-intro{max-width:1450px;margin:0 auto;padding:25px 25px 18px;display:flex;align-items:flex-end;justify-content:space-between;gap:12px}\n    .page-intro h1{font-size:25px;letter-spacing:-.65px;margin:0 0 3px;line-height:1.25}\n    .page-intro p{margin:0;color:var(--muted);font-size:13px}\n    .app-layout{max-width:1450px;padding:0 25px 35px;margin:0 auto;display:grid;grid-template-columns:365px minmax(0,1fr);gap:19px;align-items:start}\n    .panel,.preview-pane{background:#fff;border-radius:16px;border:1px solid var(--stroke);box-shadow:var(--shadow);overflow:hidden}\n    .panel-header{padding:18px 20px 13px;border-bottom:1px solid #eef1f5}\n    .panel-header .step{font-size:10px;font-weight:800;color:var(--red);letter-spacing:1.4px;text-transform:uppercase}\n    .panel-header h2{font-size:16px;letter-spacing:-.25px;margin:3px 0 2px}\n    .panel-header p{font-size:12px;color:var(--muted);margin:0}\n    .form-body{padding:18px 20px 20px}\n    .field{margin:0 0 15px}\n    .field label,.field .field-label{font-size:12px;font-weight:700;color:#344251;display:block;margin-bottom:6px}\n    .required{color:var(--red)}\n    input[type=text],input[type=url],input[type=tel],input[type=date],input[type=time],select,textarea{border:1px solid #d6dee6;border-radius:8px;background:#fff;color:var(--ink);outline:none;width:100%;padding:10px 11px;min-height:40px;transition:border .2s,box-shadow .2s}\n    input:focus,select:focus,textarea:focus{border-color:#dd0000;box-shadow:0 0 0 3px rgba(221,0,0,.09)}\n    .invalid{border-color:#dd0000!important;background:#fff6f6!important}\n    input::placeholder,textarea::placeholder{color:#95a1ab}\n    textarea{min-height:63px;resize:vertical}\n    .field-row{display:grid;grid-template-columns:1fr 1fr;gap:11px}\n    .section-line{border-top:1px solid #edf0f4;margin:18px 0 16px}\n    .mini-heading{font-size:11px;text-transform:uppercase;letter-spacing:1.1px;color:#6d7b8a;font-weight:800;margin-bottom:13px}\n    .hint{font-size:11px;color:var(--muted);margin-top:5px;line-height:1.5}\n    .checkbox-row{display:flex;align-items:flex-start;gap:11px;padding:12px;background:#fbfcfd;border:1px solid var(--stroke);border-radius:10px}\n    .checkbox-row input{width:17px;height:17px;accent-color:var(--red);margin:3px 0 0;flex:none}\n    .checkbox-row label{font-size:12px;cursor:pointer;display:block;font-weight:700}\n    .checkbox-row small{font-size:11px;display:block;color:var(--muted);font-weight:400;line-height:1.55;margin-top:3px}\n    .form-actions{display:flex;gap:9px;margin-top:17px}\n    .secondary-btn{border:1px solid #d5dde5;background:#fff;color:#344251;border-radius:8px;font-size:12px;font-weight:700;padding:10px 12px;transition:background .15s}\n    .secondary-btn:hover{background:#f5f7f9}\n    .form-actions button{flex:1}\n    .preview-top{padding:18px 20px;border-bottom:1px solid #edf0f3;display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}\n    .preview-top h2{margin:0;font-size:16px;letter-spacing:-.25px}\n    .preview-top p{margin:2px 0 0;color:var(--muted);font-size:12px}\n    .preview-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n    .primary-btn{border:none;background:var(--red);color:#fff;font-weight:750;border-radius:9px;padding:11px 14px;display:inline-flex;gap:8px;align-items:center;justify-content:center;box-shadow:0 6px 15px rgba(221,0,0,.16);transition:background .16s}\n    .primary-btn:hover{background:var(--red-dark)}\n    .subject-row{display:flex;align-items:center;gap:12px;padding:13px 21px;background:#fff;border-bottom:1px solid #edf0f4}\n    .subject-label{font-size:11px;font-weight:800;color:var(--muted);letter-spacing:.8px;text-transform:uppercase;flex:none}\n    #emailSubject{font-weight:700;min-width:175px;flex:1;overflow-wrap:anywhere;font-size:13px;min-height:38px;border:1px solid #d6dee6;border-radius:8px;padding:8px 10px;color:#273744;background:#fff}\n    .privacy-note{display:grid;gap:5px;border:1px solid #e6d8aa;background:#fff9e8;padding:11px 13px;border-radius:9px;font-size:11px;color:#735a27}.privacy-note strong{font-size:11px;color:#68491d}.privacy-note span{line-height:1.55}\n    .subject-row{gap:8px}.subject-row .subject-label{font-size:10px}\n    @media(max-width:630px){#emailSubject{flex-basis:100%;order:2}.subject-row #copySubjectBtn,.subject-row #resetSubjectBtn{order:3}}\n    .compact-btn{padding:8px 10px;white-space:nowrap}\n    .preview-well{background:#e9edf1;min-height:510px;padding:29px 18px 42px;overflow-x:auto}\n    .email-paper{margin:0 auto;max-width:666px;width:100%;background:#fff;box-shadow:0 18px 36px rgba(35,48,66,.13);border-radius:7px;overflow:hidden}\n    .preview-foot{padding:13px 19px;border-top:1px solid #e4e8ee;background:#fff;color:#637181;font-size:12px;display:flex;gap:15px;align-items:center;justify-content:space-between;flex-wrap:wrap}\n    .preview-foot b{color:#394653}\n    .note{max-width:1450px;margin:-16px auto 40px;padding:0 25px;color:#637181;font-size:12px;line-height:1.6}\n    .note strong{color:#394653}\n    .toast{position:fixed;right:23px;bottom:21px;z-index:300;background:#172735;color:#fff;padding:12px 17px;border-radius:10px;box-shadow:0 13px 35px rgba(0,0,0,.2);font-size:13px;max-width:min(400px,calc(100vw - 30px));display:none}\n    .toast.show{display:block}\n    .subtle-flag{font-size:11px;background:#fff7e9;color:#946017;border:1px solid #f5e0bd;border-radius:7px;padding:6px 10px;font-weight:650}\n    .hidden{display:none!important}\n\n    /* Standalone Candidate Submission editor — no profile-count field. */\n    .submission-rows{display:grid;gap:10px;margin:13px 0 10px}\n    .submission-entry{padding:11px 12px;background:#fafbfd;border:1px solid #e0e6ee;border-radius:10px}\n    .submission-entry-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:12px}\n    .submission-entry-head strong{font-size:12px;color:#32445a}\n    .submission-entry-head button{font-size:11px;padding:5px 8px}\n    .submission-three{display:grid;grid-template-columns:80px minmax(0,1fr) minmax(0,1fr);gap:8px}\n    .submission-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}\n    .submission-entry .field{margin-bottom:10px}\n    .submission-entry label{font-size:11px}\n    .submission-entry input{font-size:12px;min-height:36px;padding:8px}\n    .submission-add-wrapper{display:flex;flex-direction:column;justify-content:flex-start}\n    .submission-add-wrapper .secondary-btn{min-height:40px}\n    .submission-preview-table{overflow-x:auto;max-width:100%}\n    @media(max-width:650px){.submission-three{grid-template-columns:80px minmax(0,1fr)}.submission-three .field:last-child{grid-column:1/-1}.submission-two{grid-template-columns:1fr 1fr}}\n\n    /* V8: one editable recipient envelope field, with a company contact picker when supplied */\n    .recipient-row{display:flex;align-items:center;gap:10px;padding:14px 21px 9px;background:#fdfefe;border-bottom:1px solid #edf0f4;flex-wrap:wrap}\n    .recipient-label{min-width:105px;color:#637181;font-weight:800;text-transform:uppercase;letter-spacing:.55px;font-size:11px}\n    .recipient-input{flex:1;min-width:200px;min-height:40px;border:1px solid #d6dee6;border-radius:8px;padding:10px 12px;font-size:13px;font-weight:600;background:#fff}\n    .recipient-input:focus{outline:none;border-color:#dd0000;box-shadow:0 0 0 3px rgba(221,0,0,.09)}\n    .recipient-help{padding:3px 21px 10px;background:#fdfefe;border-bottom:1px solid #edf0f4;color:#778698;font-size:11px;line-height:1.45}\n    .recipient-help.warning{color:#98631f}\n    .company-contact-panel{display:flex;align-items:center;gap:9px;padding:9px 21px;background:#fdfefe;border-bottom:1px solid #edf0f4;flex-wrap:wrap}\n    .company-contact-panel label{color:#657589;font-size:11px;font-weight:750;min-width:105px}\n    .company-contact-panel select{flex:1;max-width:560px;min-width:200px;font-size:12px;min-height:36px;padding:7px 10px}\n    .recipient-row .compact-btn{min-height:38px}\n    @media(max-width:630px){.recipient-row{padding:11px 15px 8px}.recipient-label{width:100%;min-width:0}.recipient-input{min-width:0;flex:1 1 175px}.recipient-help{padding:2px 15px 10px}.company-contact-panel{padding:9px 15px}.company-contact-panel select{min-width:0;max-width:none}}\n    @media(max-width:950px){.app-layout{grid-template-columns:1fr}.panel{max-width:none}.preview-well{padding:20px 9px 28px}.page-intro{padding-top:17px}.preview-top{align-items:flex-start}}\n    @media(max-width:630px){header{padding:13px 15px}.header-right{display:none}.page-intro{padding:19px 13px 14px}.page-intro h1{font-size:22px}.app-layout{padding:0 12px 28px;gap:14px}.panel-header,.form-body{padding-left:15px;padding-right:15px}.preview-top{padding:15px}.subject-row{padding:13px 15px;flex-wrap:wrap}.preview-actions{width:100%}.primary-btn{flex:1}.preview-foot{padding:12px 15px}.note{padding:0 15px}.preview-well{min-height:0}}\n  </style>\n</head>\n<body>\n  <div class=\"top-accent\"></div>\n  <header>\n    <div class=\"brand\"><img class=\"brand-logo\" src=\"data:image/jpeg;base64,\" alt=\"Jobmitra logo\"><div class=\"brand-text\"><b>Candidate Email Studio</b><small>Offline recruiter message builder</small></div></div>\n    <div class=\"header-right\"><span>No login • No server required</span><span class=\"local-badge\"><span class=\"dot\"></span> Offline Ready</span></div>\n  </header>\n  <section class=\"page-intro\">\n    <div><h1>Recruitment emails, made simple.</h1><p>Enter candidate information, choose the update, and copy a professionally formatted email into Gmail.</p></div>\n    <span class=\"subtle-flag\" id=\"modeFlag\">Preview mode • fill required details</span>\n  </section>\n  <main class=\"app-layout\">\n    <aside class=\"panel\">\n      <div class=\"panel-header\"><span class=\"step\">Step 01 · Details</span><h2>Candidate information</h2><p>Only fields marked * are required.</p></div>\n      <div class=\"form-body\">\n        <div class=\"field\"><label for=\"candidateName\">Candidate full name <span class=\"required\">*</span></label><input id=\"candidateName\" type=\"text\" placeholder=\"e.g. Rahul Sharma\" autocomplete=\"off\" maxlength=\"120\"></div>\n        <div class=\"field\" id=\"jobPositionField\"><label for=\"jobPosition\">Job position <span class=\"required\">*</span></label><input id=\"jobPosition\" type=\"text\" placeholder=\"e.g. Python Developer\" autocomplete=\"off\" maxlength=\"150\"></div>\n        <div class=\"field\" id=\"companyNameField\"><label for=\"companyName\">Hiring company <span class=\"required\">*</span></label><input id=\"companyName\" type=\"text\" placeholder=\"e.g. ABC Technologies\" autocomplete=\"off\" maxlength=\"160\"></div>\n        <div class=\"field\" id=\"jobLocationField\"><label for=\"jobLocation\">Job location <span class=\"required\">*</span></label><input id=\"jobLocation\" type=\"text\" placeholder=\"e.g. Indore, MP\" autocomplete=\"off\" maxlength=\"160\"></div>\n        <div class=\"field\"><label for=\"candidateStatus\">Email template <span class=\"required\">*</span></label>\n          <select id=\"candidateStatus\">\n            <optgroup label=\"Jobmitra internal screening\">\n              <option value=\"jobmitra_screening\">Jobmitra Screening · Invitation</option>\n              <option value=\"screening_completed\">Screening Completed · Feedback Pending</option>\n              <option value=\"screening_cleared\">Screening Cleared</option>\n            </optgroup>\n            <optgroup label=\"Company interviews / custom rounds\">\n              <option value=\"interview_scheduled\">Company Interview · Scheduled</option>\n              <option value=\"technical_interview\">Technical Interview · Scheduled</option>\n              <option value=\"custom_round\">Custom Company Interview Round</option>\n              <option value=\"round1_completed\">Round 1 · Completed</option>\n              <option value=\"round1_cleared\">Round 1 · Cleared</option>\n              <option value=\"round2_completed\">Round 2 · Completed</option>\n              <option value=\"round2_cleared\">Round 2 · Cleared</option>\n              <option value=\"final_completed\">Final / Senior Management Interview</option>\n            </optgroup>\n            <optgroup label=\"Selection & after-selection\">\n              <option value=\"selected\" selected>Selected by Hiring Company</option>\n              <option value=\"offer_received\">Offer Shared / Received</option>\n              <option value=\"joined\">Joined Successfully</option>\n              </optgroup>\n            <optgroup label=\"Not Selected · Candidate communication\">\n              <option value=\"not_selected\">Not Selected · Candidate Application Update</option>\n            </optgroup>\n            <optgroup label=\"Company-facing coordination\">\n              <option value=\"candidate_submission\">Candidate Submission · Profiles to Company</option>\n              <option value=\"f2f_company\">F2F Interview · Confirmation to Company</option>\n            </optgroup>\n          </select><div class=\"hint\" id=\"statusHint\">Use only after the hiring company has confirmed the selection.</div><button id=\"notSelectedQuick\" type=\"button\" class=\"secondary-btn\" style=\"margin-top:9px;width:100%;background:#fff7f7;color:#a52b38;border-color:#f0d3d8;\">Not Selected · Open candidate application update</button>\n        </div>\n        <div id=\"submissionFields\" class=\"hidden\" aria-label=\"Company candidate submission\">\n          <div class=\"section-line\"></div>\n          <div class=\"mini-heading\">Candidate Submission</div>\n          <div class=\"field\"><label for=\"submissionContact\">Contact person (optional)</label><input id=\"submissionContact\" type=\"text\" placeholder=\"e.g. Hiring Team / Mr. Mehta\" maxlength=\"130\"></div>\n          <div class=\"field-row submission-start-row\">\n            <div class=\"field\"><label for=\"submissionStart\">Starting S.No. <span class=\"required\">*</span></label><input type=\"number\" id=\"submissionStart\" min=\"1\" max=\"99999\" step=\"1\" value=\"1\"><div class=\"hint\">Previously submitted 1–4? Enter 5 to continue serial numbering.</div></div>\n            <div class=\"field submission-add-wrapper\"><label>Add profiles</label><button class=\"secondary-btn\" id=\"submissionAdd\" type=\"button\">+ Add Candidate</button></div>\n          </div>\n          <div id=\"submissionRows\" class=\"submission-rows\" aria-live=\"polite\"></div>\n          <p class=\"hint\">Current and Expected CTC are optional. A salary column appears only when at least one candidate has a meaningful amount. Missing values remain —.</p>\n        </div>\n        <div id=\"otherStageFieldsHeading\"><div class=\"section-line\"></div>\n        <div class=\"mini-heading\">Stage-specific details</div></div>\n        <div class=\"field privacy-note\" id=\"candidatePrivacyNotice\"><strong>Candidate confidentiality</strong><span>Company name is excluded from candidate-facing messages until the candidate is confirmed selected. Review manual notes and meeting links, which may reveal the employer. Company-facing confirmations are handled separately.</span></div>\n        <div id=\"roundFields\" class=\"hidden\">\n          <div class=\"field-row\">\n            <div class=\"field\"><label for=\"roundName\">Interview round name <span class=\"required\">*</span></label><input id=\"roundName\" type=\"text\" maxlength=\"110\" placeholder=\"e.g. Round 3 · Director Discussion\"></div>\n            <div class=\"field\"><label for=\"roundInterviewer\">Interview panel / designation (optional)</label><input id=\"roundInterviewer\" type=\"text\" maxlength=\"110\" placeholder=\"e.g. Senior Management\"></div>\n          </div>\n          <p class=\"hint\">Use the exact configured JD round name. Dates, time, mode and meeting link are entered in the interview scheduling section below.</p>\n        </div>\n        <div id=\"interviewScheduleFields\" class=\"hidden\">\n          <div class=\"field-row\"><div class=\"field\"><label for=\"interviewDate\">Confirmed interview date</label><input id=\"interviewDate\" type=\"date\"></div><div class=\"field\"><label for=\"interviewTime\">Interview time</label><input id=\"interviewTime\" type=\"time\"></div></div>\n          <div class=\"field\"><label for=\"interviewMode\">Interview mode</label><select id=\"interviewMode\"><option value=\"\">Not specified</option><option value=\"Online\">Online</option><option value=\"In person\">In person</option><option value=\"Telephone\">Telephone</option></select></div>\n          <div class=\"field\"><label for=\"interviewMeetingLink\">Interview meeting link (optional)</label><input id=\"interviewMeetingLink\" type=\"url\" placeholder=\"https://meet.google.com/xxx-xxxx-xxx\" autocomplete=\"off\" maxlength=\"500\"><div class=\"hint\">Paste the confirmed meeting URL manually. It will appear as a clickable link in the email; no meeting will be created automatically.</div></div>\n          <div class=\"field-row\">\n            <div class=\"field\"><label for=\"interviewMeetingId\">Meeting ID (optional)</label><input id=\"interviewMeetingId\" type=\"text\" maxlength=\"120\" autocomplete=\"off\" placeholder=\"e.g. 123 456 789\"></div>\n            <div class=\"field\"><label for=\"interviewPasscode\">Meeting passcode (optional)</label><input id=\"interviewPasscode\" type=\"text\" maxlength=\"120\" autocomplete=\"off\" placeholder=\"If provided by the organizer\"></div>\n          </div>\n          <div class=\"hint\">The email displays only meeting details you enter. A blank link, ID or passcode never creates an empty table row.</div>\n        </div>\n        <div id=\"technicalInterviewFields\" class=\"hidden\">\n          <div class=\"hint\" style=\"margin:-2px 0 13px;\">Enter the interview details shared by the hiring company. This invitation is sent by Jobmitra to the candidate.</div>\n          <div class=\"field-row\">\n            <div class=\"field\"><label for=\"technicalDate\">Technical interview date <span class=\"required\">*</span></label><input id=\"technicalDate\" type=\"date\"></div>\n            <div class=\"field\"><label for=\"technicalTime\">Interview time <span class=\"required\">*</span></label><input id=\"technicalTime\" type=\"time\"></div>\n          </div>\n          <div class=\"field\"><label for=\"technicalMeetingLink\">Interview meeting link (or provide Meeting ID below)</label><input id=\"technicalMeetingLink\" type=\"url\" placeholder=\"https://teams.microsoft.com/meet/...\" autocomplete=\"off\" maxlength=\"1000\"><div class=\"hint\">Paste the company's confirmed joining URL. It appears in the email as a clickable link. No meeting is created automatically.</div></div>\n          <div class=\"field-row\">\n            <div class=\"field\"><label for=\"technicalMeetingId\">Meeting ID (if provided)</label><input id=\"technicalMeetingId\" type=\"text\" placeholder=\"e.g. 414 267 929\" autocomplete=\"off\" maxlength=\"120\"></div>\n            <div class=\"field\"><label for=\"technicalPasscode\">Meeting passcode (if provided)</label><input id=\"technicalPasscode\" type=\"text\" placeholder=\"From company invite\" autocomplete=\"off\" maxlength=\"120\"></div>\n          </div>\n          <div class=\"hint\">The interview date, time and either a meeting URL or Meeting ID are required before copying. Use Additional note for instructions from the company.</div>\n        </div>\n        <div id=\"finalInterviewFields\" class=\"hidden\">\n          <div class=\"hint\" style=\"margin:-2px 0 13px;\">Enter the confirmed final interview details provided by the hiring company. Only the candidate name and meeting details appear in this email.</div>\n          <div class=\"field-row\">\n            <div class=\"field\"><label for=\"finalDate\">Final interview date <span class=\"required\">*</span></label><input id=\"finalDate\" type=\"date\"></div>\n            <div class=\"field\"><label for=\"finalTime\">Interview time <span class=\"required\">*</span></label><input id=\"finalTime\" type=\"time\"></div>\n          </div>\n          <div class=\"field\"><label for=\"finalMeetingLink\">Meeting link (or provide Meeting ID below)</label><input id=\"finalMeetingLink\" type=\"url\" placeholder=\"https://teams.microsoft.com/meet/...\" autocomplete=\"off\" maxlength=\"1000\"><div class=\"hint\">Use the company's confirmed meeting link. It will be clickable in the email.</div></div>\n          <div class=\"field-row\">\n            <div class=\"field\"><label for=\"finalMeetingId\">Meeting ID (if provided)</label><input id=\"finalMeetingId\" type=\"text\" autocomplete=\"off\" maxlength=\"120\" placeholder=\"Meeting ID\"></div>\n            <div class=\"field\"><label for=\"finalPasscode\">Passcode (if provided)</label><input id=\"finalPasscode\" type=\"text\" autocomplete=\"off\" maxlength=\"120\" placeholder=\"Passcode\"></div>\n          </div>\n          <div class=\"hint\">Candidate name, interview date and time are required, plus either a meeting link or Meeting ID. The readiness checklist is included automatically.</div>\n        </div>\n        <div id=\"faceToFaceFields\" class=\"hidden\">\n          <div class=\"hint\" style=\"margin:-2px 0 13px;\">This confirmation is addressed to the hiring company. The weekday is calculated automatically from the interview date.</div>\n          <div class=\"field-row\"><div class=\"field\"><label for=\"f2fDate\">Interview date <span class=\"required\">*</span></label><input id=\"f2fDate\" type=\"date\"></div><div class=\"field\"><label for=\"f2fTime\">Interview time <span class=\"required\">*</span></label><input id=\"f2fTime\" type=\"time\"></div></div>\n          <div class=\"field\"><label for=\"f2fVenue\">Face-to-face interview venue / full address <span class=\"required\">*</span></label><textarea id=\"f2fVenue\" rows=\"3\" maxlength=\"600\" placeholder=\"e.g. 708, City Avenue M Building, Mumbai-Bangalore Highway, Wakad, Pune, Maharashtra 411057\"></textarea></div>\n        </div>\n        <div id=\"nextScheduleFields\" class=\"hidden\">\n          <div class=\"field-row\"><div class=\"field\"><label for=\"nextDate\">Confirmed next-round date</label><input id=\"nextDate\" type=\"date\"></div><div class=\"field\"><label for=\"nextTime\">Next-round time</label><input id=\"nextTime\" type=\"time\"></div></div>\n        </div>\n        <div id=\"joiningFields\" class=\"hidden\">\n          <div class=\"field\"><label for=\"joiningDate\">Confirmed joining date</label><input id=\"joiningDate\" type=\"date\"><div class=\"hint\">Leave blank if the employer has not confirmed the date.</div></div>\n        </div>\n        <div class=\"section-line\"></div>\n        <div class=\"mini-heading\">Sender &amp; personal touch</div>\n        <div class=\"field-row\"><div class=\"field\"><label for=\"recruiterName\">Recruiter name</label><input id=\"recruiterName\" type=\"text\" placeholder=\"Team Jobmitra\" maxlength=\"100\"></div><div class=\"field\"><label for=\"recruiterPhone\">Contact number</label><input id=\"recruiterPhone\" type=\"tel\" placeholder=\"Optional\" maxlength=\"35\"></div></div>\n        <div class=\"field\"><label for=\"personalNote\">Additional note (optional)</label><textarea id=\"personalNote\" maxlength=\"750\" placeholder=\"e.g. Please keep your ID and updated resume ready.\"></textarea><div class=\"hint\">Appears in a separate note block. No private notes should be added accidentally.</div></div>\n        \n        <div class=\"form-actions\"><button type=\"button\" class=\"secondary-btn\" id=\"sampleBtn\">Load demo details</button><button type=\"button\" class=\"secondary-btn\" id=\"clearBtn\">Clear all</button></div>\n      </div>\n    </aside>\n    <section class=\"preview-pane\">\n      <div class=\"preview-top\"><div><h2>Live email preview</h2><p>Branded HTML formatting, ready for Gmail.</p></div><div class=\"preview-actions\"><button class=\"secondary-btn\" id=\"downloadBtn\" type=\"button\">↓ Download HTML</button><button class=\"primary-btn\" id=\"copyEmailBtn\" type=\"button\">⧉ &nbsp;Copy Formatted Email</button></div></div>\n      <div class=\"recipient-row\">\n      <label class=\"recipient-label\" for=\"recipientEmail\" id=\"recipientEmailLabel\">TO · Candidate</label>\n      <input id=\"recipientEmail\" class=\"recipient-input\" type=\"email\" inputmode=\"email\" autocomplete=\"email\" maxlength=\"254\" placeholder=\"Candidate email — fetched when linked to profile\" aria-describedby=\"recipientEmailHelp\">\n      <button id=\"copyRecipientBtn\" class=\"secondary-btn compact-btn\" type=\"button\">Copy To</button>\n    </div>\n    <div class=\"recipient-help warning\" id=\"recipientEmailHelp\" role=\"status\" aria-live=\"polite\">No candidate email available in this standalone preview. Enter it manually or open the Studio from Candidate Desk.</div>\n    <div class=\"company-contact-panel hidden\" id=\"companyContactPanel\">\n      <label for=\"companyContactSelect\">Company contact</label>\n      <select id=\"companyContactSelect\"><option value=\"\">Choose a contact from Company Details</option></select>\n    </div>\n    <div class=\"subject-row\"><label class=\"subject-label\" for=\"emailSubject\">Subject · editable</label><input id=\"emailSubject\" type=\"text\" maxlength=\"200\" aria-label=\"Editable email subject\" placeholder=\"Email subject\" autocomplete=\"off\"><button class=\"secondary-btn compact-btn\" id=\"resetSubjectBtn\" type=\"button\">Reset subject</button><button class=\"secondary-btn compact-btn\" id=\"copySubjectBtn\" type=\"button\">Copy subject</button></div>\n      <div class=\"preview-well\"><div class=\"email-paper\" id=\"emailBody\" aria-label=\"Generated email preview\"></div></div>\n      <div class=\"preview-foot\"><span><b>How to use:</b> Copy subject → paste into Gmail subject. Copy formatted email → paste into Gmail body.</span><span>Always review before sending.</span></div>\n    </section>\n  </main>\n  <p class=\"note\"><strong>Privacy &amp; delivery:</strong> This HTML app runs locally on your computer and does not upload candidate information. It does not send emails. The employee must check the candidate's status and details, then send manually from Gmail. <strong>Round completed</strong> and <strong>round cleared</strong> are deliberately different statuses.</p>\n  <div id=\"toast\" class=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n  <script>\n\n\n  (() => {\n    'use strict';\n    const REVIEW_URL = 'https://g.page/r/Cf-z7ybH4UE0EAE/review';\n    const WEBSITE_URL = 'https://www.jobmitra.com/';\n    const LOGO_DATA_URL = 'data:image/jpeg;base64,';\n    const REQUIRED = ['candidateName','jobPosition'];\n    const SUBMISSION_REQUIRED = ['jobPosition','companyName'];\n    const COMPANY_REQUIRED=['companyName','candidateName','jobPosition','f2fDate','f2fTime','f2fVenue'];\n    const F2F_REQUIRED = ['candidateName','jobPosition','companyName','f2fDate','f2fTime','f2fVenue'];\n    const TECHNICAL_REQUIRED = ['candidateName','jobPosition','technicalDate','technicalTime'];\n    const FINAL_REQUIRED = ['candidateName','finalDate','finalTime'];\n    const DEMO_REQUIRED = {candidateName:'Rahul Sharma',jobPosition:'Python Developer',companyName:'ABC Technologies',jobLocation:'Indore, Madhya Pradesh'};\n    const STAGES_WITH_NEXT = ['round1_cleared','round2_cleared'];\n    const STAGES_WITH_JOINING = ['selected','offer_received','joined'];\n    const $ = (id) => document.getElementById(id);\n    const escapeHtml = (val) => String(val ?? '').replace(/[&<>\"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n    const get = (id) => $(id).value.trim();\n    const getRequiredFields = () => get('candidateStatus')==='candidate_submission' ? SUBMISSION_REQUIRED : get('candidateStatus')==='f2f_company' ? COMPANY_REQUIRED : get('candidateStatus')==='custom_round' ? ['candidateName','jobPosition','roundName','interviewDate','interviewTime'] : get('candidateStatus')==='technical_interview' ? ['candidateName','jobPosition','technicalDate','technicalTime'] : get('candidateStatus')==='final_completed' ? ['candidateName','jobPosition','finalDate','finalTime'] : ['candidateName','jobPosition'];\n    function getMeetingUrl(fieldId = 'interviewMeetingLink') {\n      const raw = get(fieldId);\n      if (!raw) return '';\n      try {\n        const url = new URL(raw);\n        return (url.protocol === 'https:' || url.protocol === 'http:') && !url.username && !url.password && url.hostname.includes('.') ? url.href : '';\n      } catch (_) { return ''; }\n    }\n    const val = (id, fallback) => escapeHtml(get(id) || fallback);\n    const capitalize = (s) => s ? s[0].toUpperCase()+s.slice(1) : s;\n    let isDemo = false;\n    let customizedSubject = '';\n    let currentSubjectStage = '';\n    let toastTimeout = null;\n\n    // Recipient addresses are envelope metadata only, never inserted into candidate-facing HTML.\n    // In production, Candidate Desk resolves canonical candidate.email and Company Details resolves\n    // the contact email via the selected JD's company_id. This standalone file has no database access.\n    const recipientEmailRegex=/^[^\\s@,;]+@[^\\s@,;]+\\.[^\\s@,;]+$/;\n    const recipientDefaults={candidate:'',company:''};\n    const recipientEdited={candidate:'',company:''};\n    const recipientOrigins={candidate:'',company:''};\n    const recipientContextNames={candidate:'',company:''};\n    let recipientKindActive=null;\n    let companyContactOptions=[];\n    const recipientKind=status=>['candidate_submission','f2f_company'].includes(status)?'company':'candidate';\n    const cleanRecipientEmail=email=>String(email||'').trim();\n    const recipientValid=email=>recipientEmailRegex.test(cleanRecipientEmail(email));\n    function setCompanyContactOptions(items=[]){\n      const seen=new Set();companyContactOptions=[];\n      for(const c of items){\n        const email=cleanRecipientEmail(typeof c==='string'?c:c?.email);\n        if(!recipientValid(email)||seen.has(email.toLowerCase()))continue;\n        seen.add(email.toLowerCase());\n        companyContactOptions.push({email,name:String(c?.name||c?.contact_name||c?.role||'Company contact'),primary:Boolean(c?.is_primary||c?.isPrimary||c?.primary)});\n      }\n      const select=$('companyContactSelect');select.replaceChildren();\n      select.add(new Option('Choose company contact', ''));\n      for(const c of companyContactOptions)select.add(new Option(`${c.name}${c.primary?' · Primary':''} — ${c.email}`,c.email));\n      select.value=companyContactOptions.some(x=>x.email===get('recipientEmail'))?get('recipientEmail'):'';\n    }\n    function refreshRecipient(){\n      const kind=recipientKind(get('candidateStatus'));\n      const switchKind=kind!==recipientKindActive;\n      recipientKindActive=kind;\n      const label=$('recipientEmailLabel'),input=$('recipientEmail');\n      label.textContent=kind==='company'?'To · Company':'To · Candidate';\n      input.setAttribute('aria-label',kind==='company'?'Company contact email (editable)':'Candidate email (editable)');\n      input.placeholder=kind==='company'?'Company Details contact email — editable':'Candidate profile email — editable';\n      $('companyContactPanel').classList.toggle('hidden',kind!=='company'||companyContactOptions.length===0);\n      if(switchKind)input.value=recipientEdited[kind]||recipientDefaults[kind]||'';\n      const email=cleanRecipientEmail(input.value);\n      const from=recipientOrigins[kind];\n      const hint=$('recipientEmailHelp');hint.classList.toggle('warning',!recipientValid(email));\n      hint.textContent=!email?\n        (kind==='company'?'No company email available. Choose a saved Company Details contact or enter one manually.':'No candidate email available. Open from Candidate Desk or enter it manually.'):\n        (!recipientValid(email)?'Please enter one valid email address before using it as a recipient.':\n          (recipientEdited[kind]?'Manually editable recipient · verify before sending':from==='company'?'Prefilled from Company Details · editable':from==='candidate'?'Prefilled from Candidate Profile · editable':'Recipient entered · verify before sending'));\n      if(kind==='company')$('companyContactSelect').value=companyContactOptions.some(x=>x.email===email)?email:'';\n    }\n    function clearRecipientState(){\n      for(const k of ['candidate','company']){recipientDefaults[k]='';recipientEdited[k]='';recipientOrigins[k]='';recipientContextNames[k]='';}\n      recipientKindActive=null;setCompanyContactOptions([]);$('recipientEmail').value='';refreshRecipient();\n    }\n    function applyStudioContext(ctx){\n      if(!ctx||typeof ctx!=='object'||Array.isArray(ctx))return;\n      clearRecipientState();\n      // Context may be supplied by a future validated SQLite-backed JD/Candidate Desk route.\n      const named={candidateName:'candidateName',jobPosition:'jobTitle',companyName:'companyName',jobLocation:'location',\n        interviewDate:'interviewDate',interviewTime:'interviewTime',joiningDate:'joiningDate'};\n      for(const [id,key] of Object.entries(named))if(Object.prototype.hasOwnProperty.call(ctx,key))$(id).value=String(ctx[key]||'');\n      if(ctx.status && [...$('candidateStatus').options].some(opt=>opt.value===ctx.status))$('candidateStatus').value=ctx.status;\n      if(ctx.interviewMode)$('interviewMode').value=String(ctx.interviewMode);\n      if(ctx.meetingLink)$('interviewMeetingLink').value=String(ctx.meetingLink);\n      if(ctx.meetingId)$('interviewMeetingId').value=String(ctx.meetingId);\n      if(ctx.passcode)$('interviewPasscode').value=String(ctx.passcode);\n      const companyEmail=cleanRecipientEmail(ctx.companyEmail||ctx.companyContactEmail||ctx.company?.email);\n      const candidateEmail=cleanRecipientEmail(ctx.candidateEmail||ctx.candidate?.email);\n      if(recipientValid(candidateEmail)){recipientDefaults.candidate=candidateEmail;recipientOrigins.candidate='candidate';}\n      const contacts=Array.isArray(ctx.companyContacts)?ctx.companyContacts:[];\n      setCompanyContactOptions(contacts);\n      const primary=companyContactOptions.find(c=>c.primary);\n      const preferred=primary?.email||(recipientValid(companyEmail)?companyEmail:(companyContactOptions[0]?.email||''));\n      if(preferred){recipientDefaults.company=preferred;recipientOrigins.company='company';}\n      recipientContextNames.candidate=get('candidateName');recipientContextNames.company=get('companyName');\n      if(ctx.startSerial!=null&&Number.isInteger(Number(ctx.startSerial))&&Number(ctx.startSerial)>0)$('submissionStart').value=String(ctx.startSerial);\n      if(Array.isArray(ctx.candidates)&&ctx.candidates.length){\n        const first=Number($('submissionStart').value)||1;\n        submissionRows=ctx.candidates.slice(0,50).map((r,i)=>({id:submissionSeq++,serial:(Number.isInteger(Number(r.serial))&&Number(r.serial)>0?Number(r.serial):first+i),name:String(r.name||''),experience:String(r.experience||''),currentCTC:String(r.currentCTC||''),expectedCTC:String(r.expectedCTC||''),notice:String(r.notice||'')}));\n        renderSubmissionEditor();\n      }\n      isDemo=false;currentSubjectStage='';customizedSubject='';recipientKindActive=null;refreshRecipient();build();\n    }\n    function invalidateRecipientOnNameChange(kind){\n      const current=kind==='company'?get('companyName'):get('candidateName');\n      if(!recipientContextNames[kind]||current===recipientContextNames[kind])return;\n      recipientContextNames[kind]='';recipientDefaults[kind]='';recipientEdited[kind]='';recipientOrigins[kind]='';\n      if(kind==='company')setCompanyContactOptions([]);\n      if(recipientKind(get('candidateStatus'))===kind)$('recipientEmail').value='';\n    }\n    async function copyRecipient(){\n      const email=cleanRecipientEmail(get('recipientEmail'));\n      if(!recipientValid(email)){$('recipientEmail').classList.add('invalid');$('recipientEmail').focus();showToast('Enter a valid To email address before copying the recipient.',true);return;}\n      try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(email);showToast('Recipient copied. Paste it into Gmail To.');return;}}catch(e){}\n      const area=document.createElement('textarea');area.value=email;area.style.cssText='position:fixed;opacity:0';document.body.appendChild(area);area.select();\n      const ok=document.execCommand('copy');area.remove();showToast(ok?'Recipient copied. Paste it into Gmail To.':'Could not copy. Select the To email manually.',!ok);\n    }\n    window.JobmitraEmailStudio=Object.freeze({setContext:applyStudioContext});\n    window.addEventListener('message',e=>{\n      // Parent-to-embedded-studio bridge; never accept arbitrary window messages.\n      if(e.source!==window.parent||e.data?.type!=='jobmitra-email-prefill')return;\n      if(window.location.origin!=='null'&&e.origin!==window.location.origin)return;\n      applyStudioContext(e.data.context);\n    });\n\n    const statusHints = {\n      jobmitra_screening:'Jobmitra internal screening: share only the role and confirmed schedule. Never disclose the client name.',\n      screening_completed:'Jobmitra screening completed; feedback remains pending. Do not communicate selection yet.',\n      screening_cleared:'Use only after Jobmitra has confirmed internal screening clearance.',\n      custom_round:'Use the exact configured interview round label; verify date, mode and meeting details before sharing.', \n      interview_scheduled:'Use this stage only after the interview has been confirmed by the employer.',\n      f2f_company:'For a confirmed face-to-face interview: send this email to the hiring company / interview panel.',\n      technical_interview:'After the first interview, forward the confirmed company-provided technical round invitation to the candidate.',\n      round1_completed:'Interview attended; no pass/fail decision is being communicated.',\n      round1_cleared:'Use only after Round 1 clearance has been confirmed.',\n      round2_completed:'Interview attended; no pass/fail decision is being communicated.',\n      round2_cleared:'Use only after Round 2 clearance has been confirmed.',\n      final_completed:'Send the company-confirmed senior management interview invitation and readiness checklist to the candidate.',\n      selected:'Use only after the hiring company has confirmed the selection.',\n      offer_received:'Use when the actual employer offer has been shared or received.',\n      joined:'Use only after the candidate has actually joined the employer.',\n      candidate_submission:'Send selected candidate profiles to the hiring company. This is a draft/copy-only action and does not record a submission.',\n      not_selected:'Not Selected: a respectful candidate-facing update, without the hiring company’s identity. Use only after the outcome is confirmed.'\n    };\n    function formatDate(v) {\n      if (!v || !/^\\d{4}-\\d{2}-\\d{2}$/.test(v)) return '';\n      const [y,m,d] = v.split('-').map(Number);\n      const date = new Date(y,m-1,d,12);\n      if (date.getFullYear()!==y || date.getMonth()!==m-1 || date.getDate()!==d) return '';\n      return new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'long',year:'numeric'}).format(date);\n    }\n    function formatWeekday(v) {\n      if (!v || !/^\\d{4}-\\d{2}-\\d{2}$/.test(v)) return '';\n      const [y,m,d] = v.split('-').map(Number);\n      const date = new Date(y,m-1,d,12);\n      if (date.getFullYear()!==y || date.getMonth()!==m-1 || date.getDate()!==d) return '';\n      return new Intl.DateTimeFormat('en-IN',{weekday:'long'}).format(date);\n    }\n    function formatNumericDate(v) {\n      if (!formatDate(v)) return '';\n      const [y,m,d] = v.split('-');\n      return `${d}/${m}/${y}`;\n    }\n    function formatTime(v) {\n      if (!v || !/^\\d{2}:\\d{2}$/.test(v)) return '';\n      const [h,m] = v.split(':').map(Number);\n      if (h>23 || m>59) return '';\n      return String(h%12||12)+':'+String(m).padStart(2,'0')+(h>=12?' PM':' AM');\n    }\n    function joinDateTime(date,time) {\n      const day = formatDate(date); const clock = formatTime(time);\n      return day ? `${escapeHtml(day)}${clock ? ' at '+escapeHtml(clock) : ''}` : '';\n    }\n    // Shared, email-client-safe readiness guidance for COMPANY candidate-facing interviews.\n    // Jobmitra's own screening and employer-facing confirmation intentionally exclude it.\n    // Short company-interview readiness note. Internal Jobmitra screening is excluded.\n    // No separate 10-minute notice or long sectioned checklist.\n    function companyInterviewReadinessHtml(mode='Online') {\n      const modeKey=String(mode||'Online').trim().toLowerCase();\n      const inPerson=['in person','face-to-face','f2f'].includes(modeKey);\n      const phone=['telephone','phone'].includes(modeKey);\n      const bullets=inPerson?[\n        ['Interview Logistics','Confirm the venue and plan your travel in advance.'],\n        ['Interview Environment','Arrive at the confirmed location and follow the reception instructions.'],\n        ['Professional Appearance','Wear formal attire and be well-groomed.'],\n        ['Interview Readiness','Be ready and arrive 5–10 minutes early.']\n      ]:phone?[\n        ['Technical Setup','Keep your phone charged, with stable network coverage and clear audio.'],\n        ['Interview Environment','Choose a quiet, distraction-free place.'],\n        ['Professional Appearance','Maintain a professional and courteous manner.'],\n        ['Interview Readiness','Be ready and available 5–10 minutes early.']\n      ]:[\n        ['Technical Setup','Stable internet and clear audio.'],\n        ['Interview Environment','Choose a quiet, distraction-free place with good lighting and a clean, professional background.'],\n        ['Professional Appearance','Wear formal attire and be well-groomed.'],\n        ['Interview Readiness','Be ready and join the interview 5–10 minutes early.']\n      ];\n      return `<tr><td style=\"padding:0 37px 25px;\">\n        <h2 style=\"font-family:Arial,sans-serif;font-size:17px;line-height:1.35;margin:2px 0 9px;color:#1c2732;\">Interview Readiness Guidelines</h2>\n        <p style=\"font-family:Arial,sans-serif;font-size:12px;line-height:1.7;margin:0 0 11px;color:#485568;\">Please ensure you are fully prepared and interview-ready.</p>\n        <ul style=\"font-family:Arial,sans-serif;font-size:12px;line-height:1.75;color:#435164;margin:0;padding-left:19px;\">${bullets.map(([label,text])=>`<li style=\"margin:0 0 5px;\"><strong>${label}:</strong> ${text}</li>`).join('')}</ul>\n      </td></tr>`;\n    }\n    let submissionSeq=1;\n    let submissionRows=[{id:submissionSeq++,serial:1,name:'',experience:'',currentCTC:'',expectedCTC:'',notice:''}];\n    const submissionValue=v=>escapeHtml(String(v??''));\n    const provided=v=>!['','—','-','--','unknown','not recorded','n/a','na','none','null'].includes(String(v||'').trim().toLowerCase());\n    function renderSubmissionEditor(){\n      $('submissionRows').innerHTML=submissionRows.map((r,i)=>`<article class=\"submission-entry\" data-submission-id=\"${r.id}\">\n        <div class=\"submission-entry-head\"><strong>Candidate ${i+1}</strong><button type=\"button\" class=\"secondary-btn\" data-remove-submission=\"${r.id}\" ${submissionRows.length===1?'disabled':''}>Remove</button></div>\n        <div class=\"submission-three\">\n          <div class=\"field\"><label>S.No.</label><input type=\"number\" min=\"1\" max=\"99999\" step=\"1\" data-sub-field=\"serial\" data-sub-id=\"${r.id}\" value=\"${r.serial}\" aria-label=\"Serial number\"></div>\n          <div class=\"field\"><label>Candidate Name <span class=\"required\">*</span></label><input type=\"text\" maxlength=\"120\" data-sub-field=\"name\" data-sub-id=\"${r.id}\" value=\"${submissionValue(r.name)}\" placeholder=\"Candidate full name\"></div>\n          <div class=\"field\"><label>Experience</label><input type=\"text\" maxlength=\"95\" data-sub-field=\"experience\" data-sub-id=\"${r.id}\" value=\"${submissionValue(r.experience)}\" placeholder=\"3 years 6 months\"></div>\n        </div>\n        <div class=\"submission-two\">\n          <div class=\"field\"><label>Current CTC (optional)</label><input type=\"text\" maxlength=\"90\" data-sub-field=\"currentCTC\" data-sub-id=\"${r.id}\" value=\"${submissionValue(r.currentCTC)}\" placeholder=\"₹4,50,000 / year\"></div>\n          <div class=\"field\"><label>Expected CTC (optional)</label><input type=\"text\" maxlength=\"90\" data-sub-field=\"expectedCTC\" data-sub-id=\"${r.id}\" value=\"${submissionValue(r.expectedCTC)}\" placeholder=\"₹6,00,000 / year\"></div>\n        </div>\n        <div class=\"field\"><label>Notice Period</label><input type=\"text\" maxlength=\"110\" data-sub-field=\"notice\" data-sub-id=\"${r.id}\" value=\"${submissionValue(r.notice)}\" placeholder=\"e.g. 30 days / Immediate\"></div>\n      </article>`).join('');\n    }\n    function resetSubmissionEditor(){submissionSeq=1;submissionRows=[{id:submissionSeq++,serial:1,name:'',experience:'',currentCTC:'',expectedCTC:'',notice:''}];$('submissionStart').value='1';$('submissionContact').value='';renderSubmissionEditor();}\n    function submissionTableHTML(){\n      // Omit an optional compensation column entirely when no meaningful values are present.\n      const showCurrent=submissionRows.some(r=>provided(r.currentCTC));\n      const showExpected=submissionRows.some(r=>provided(r.expectedCTC));\n      const head=[['S.No.','serial'],['Candidate Name','name'],['Experience','experience'],...(showCurrent?[['Current CTC','currentCTC']]:[]),...(showExpected?[['Expected CTC','expectedCTC']]:[]),['Notice Period','notice']];\n      const th='font-family:Arial,sans-serif;background:#f7f8fa;font-size:11px;font-weight:bold;color:#293a4c;border:1px solid #e3e8ed;padding:11px 9px;text-align:left;';\n      const td='font-family:Arial,sans-serif;font-size:12px;line-height:1.6;color:#405161;border:1px solid #e3e8ed;padding:11px 9px;vertical-align:top;';\n      return `<div class=\"submission-preview-table\"><table role=\"table\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border-collapse:collapse;width:100%;min-width:400px;table-layout:auto\"><thead><tr>${head.map(([label])=>`<th scope=\"col\" style=\"${th}\">${escapeHtml(label)}</th>`).join('')}</tr></thead><tbody>${submissionRows.map((r,i)=>`<tr>${head.map(([label,key])=>`<td style=\"${td}background:${i%2?'#ffffff':'#fffafb'}\">${escapeHtml(key==='serial'?String(r.serial):provided(r[key])?String(r[key]):'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;\n    }\n    function validateSubmission(){\n      const serials=new Set();\n      const n=Number(get('submissionStart'));\n      if(!Number.isInteger(n)||n<1||n>99999){$('submissionStart').focus();showToast('Starting S.No. must be a positive whole number.',true);return false;}\n      for(const r of submissionRows){\n        const row=$('submissionRows').querySelector(`[data-submission-id=\"${r.id}\"]`);\n        if(!r.name.trim()){row.querySelector('[data-sub-field=\"name\"]').focus();showToast('Enter the name for every candidate.',true);return false;}\n        if(!Number.isInteger(r.serial)||r.serial<1||r.serial>99999||serials.has(r.serial)){\n          row.querySelector('[data-sub-field=\"serial\"]').focus();showToast('Serial numbers must be unique positive whole numbers.',true);return false;\n        }\n        serials.add(r.serial);\n      }\n      return true;\n    }\n    renderSubmissionEditor();\n    function stageContent(data) {\n      const {name,role,company,location,status} = data;\n      const confirmedInterview = joinDateTime(get('interviewDate'),get('interviewTime'));\n      const confirmedNext = joinDateTime(get('nextDate'),get('nextTime'));\n      const confirmedJoining = formatDate(get('joiningDate'));\n      const mode = escapeHtml(get('interviewMode'));\n      const meetingUrl = getMeetingUrl();\n      // Optional credentials: render only rows with supplied and validated values.\n      const meetingId = get('interviewMeetingId');\n      const meetingPasscode = get('interviewPasscode');\n      const meetingLinkCell = meetingUrl\n        ? `<a href=\"${escapeHtml(meetingUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#dd0000;text-decoration:underline;font-weight:bold;overflow-wrap:anywhere;word-break:break-word;\">Join interview meeting</a><br><a href=\"${escapeHtml(meetingUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#44515e;font-size:11px;font-weight:normal;text-decoration:underline;overflow-wrap:anywhere;word-break:break-all;\">${escapeHtml(meetingUrl)}</a>`\n        : '';\n      const optionalMeetingRows = [\n        ...(meetingUrl ? [{label:'Meeting Link',value:meetingLinkCell}] : []),\n        ...(meetingId ? [{label:'Meeting ID',value:escapeHtml(meetingId)}] : []),\n        ...(meetingPasscode ? [{label:'Passcode',value:escapeHtml(meetingPasscode)}] : [])\n      ];\n      const basic = [{label:'Position',value:role},{label:'Job location',value:location}];\n      const verifiedCompanyDetail = {label:'Hiring company',value:company};\n      let content;\n      switch(status) {\n      case 'candidate_submission': {\n          const roleRaw=get('jobPosition')||'[Job Title]';\n          const contact=val('submissionContact','Hiring Team');\n          const table=submissionTableHTML();\n          content={\n            recipient:'company',\n            greeting:`Dear <strong>${contact}</strong>,`,\n            subject:`Candidate Profiles for Review | ${roleRaw} | Jobmitra`,\n            eyebrow:'JOBMITRA · CANDIDATE SUBMISSION',\n            title:roleRaw,\n            sub:'',\n            intro:`We are pleased to share the following candidates shortlisted by <strong>Jobmitra</strong> for the <strong>${role}</strong> position. Kindly review their profiles and advise the next steps.`,\n            hideStatusBox:true,\n            hideReview:true,\n            footerText:'The above candidates have been shortlisted and recommended by Jobmitra for the hiring company’s independent evaluation. No hiring decision is implied by this submission.',\n            customBodyHtml:`<tr><td style=\"padding:0 37px 20px;\">${table}</td></tr><tr><td style=\"padding:0 37px 22px;\"><p style=\"font-family:Arial,sans-serif;font-size:13px;line-height:1.8;color:#405161;margin:0;\">Please share your feedback on the suitable profiles and let us know which candidates you would like to proceed with for the next stage of the hiring process.</p></td></tr>`,\n            details:[], statusLabel:'Candidate Submission'\n          };break;\n        }\n        case 'jobmitra_screening': {\n          content={subject:`Jobmitra Screening Invitation | ${get('jobPosition')||'[Position]'} | Jobmitra`,\n            eyebrow:'JOBMITRA SCREENING',title:'Your screening with Jobmitra',sub:'A step towards exploring your next opportunity.',\n            intro:`Thank you for your interest in the <strong>${role}</strong> opportunity. We would like to schedule an initial screening discussion with the Jobmitra recruitment team.`,statusLabel:'Jobmitra Screening',\n            details:[{label:'Position',value:role},...(confirmedInterview?[{label:'Screening schedule',value:confirmedInterview}]:[]),...(mode?[{label:'Mode',value:mode}]:[]),...optionalMeetingRows],\n            body:confirmedInterview?`Your Jobmitra screening is planned for <strong>${confirmedInterview}</strong>. We will discuss your experience, relevant skills, job preferences, availability and any questions you may have.`:'Our recruiter will confirm the screening date and time with you. The discussion focuses on your background, skills and suitability for this opportunity.',\n            next:'Please reply to confirm your availability or suggest another convenient time.'};break;\n        }\n        case 'screening_completed':\n          content={subject:`Screening Update | ${get('jobPosition')||'[Position]'} | Jobmitra`,eyebrow:'SCREENING UPDATE',title:'Thank you for speaking with Jobmitra',sub:'We will share the next update once available.',intro:`Thank you for taking the time to complete your Jobmitra screening for the <strong>${role}</strong> opportunity.`,statusLabel:'Screening Completed',details:[{label:'Position',value:role}],body:'Our team is reviewing the information discussed. No decision regarding progression has been communicated at this stage.',next:'We appreciate your time and will contact you when a relevant update is available.'};break;\n        case 'screening_cleared':\n          content={subject:`Screening Result | ${get('jobPosition')||'[Position]'} | Jobmitra`,eyebrow:'SCREENING UPDATE',title:'You have cleared the Jobmitra screening',sub:'Your profile is ready for the next recruitment step.',intro:`We are pleased to confirm that you have cleared the Jobmitra screening for the <strong>${role}</strong> opportunity.`,statusLabel:'Screening Cleared',details:[{label:'Position',value:role}],body:'This confirms completion of Jobmitra’s internal screening, not selection by the employer. We will share your next step when it has been arranged.',next:'Thank you for your cooperation. Our team will keep you informed.'};break;\n        case 'custom_round': {\n          const round=val('roundName','[Interview Round]');const panel=val('roundInterviewer','');\n          content={subject:`${get('roundName')||'Interview Round'} | ${get('jobPosition')||'[Position]'} | Jobmitra`,eyebrow:'INTERVIEW INVITATION',title:`${round} — interview details`,sub:'Please review your interview schedule.',intro:`Your <strong>${round}</strong> for the <strong>${role}</strong> opportunity is being coordinated by Jobmitra.`,statusLabel:round,details:[{label:'Position',value:role},{label:'Round',value:round},...(confirmedInterview?[{label:'Interview schedule',value:confirmedInterview}]:[]),...(mode?[{label:'Mode',value:mode}]:[]),...(panel?[{label:'Interview panel',value:panel}]:[]),...optionalMeetingRows],body:confirmedInterview?`The discussion is scheduled for <strong>${confirmedInterview}</strong>. Please be available a few minutes in advance.`:'The date and time will be shared once confirmed. Please do not treat this preview as a finalized invitation.',next:'If you need to reschedule or clarify anything, please reply to the Jobmitra team.'};break;\n        }\n\n        case 'interview_scheduled':\n          content = {\n            subject:`Interview Confirmation | ${get('jobPosition')||'[Position]'} — ${get('companyName')||'[Company]'}`,\n            eyebrow:'INTERVIEW INVITATION',title:'Your interview is scheduled',sub:'An important step in your career journey.',\n            intro:`We are pleased to share an interview update for the <strong>${role}</strong> opportunity with <strong>${company}</strong>.`,\n            statusLabel:'Interview Scheduled',\n            details:[...basic, ...(confirmedInterview?[{label:'Interview schedule',value:confirmedInterview}]:[]), ...(mode?[{label:'Interview mode',value:mode}]:[]), ...optionalMeetingRows],\n            body:confirmedInterview ? `Your interview has been arranged for <strong>${confirmedInterview}</strong>.${mode?' The mode is <strong>'+mode+'</strong>.':''} Please be ready a few minutes early and keep any requested documents handy.` : (meetingUrl ? 'The meeting link is provided above. Our recruitment team will share the confirmed interview date and time as soon as they are available.' : 'Our recruitment team will share the confirmed interview date, time and instructions as soon as they are available.'),\n            next:'Please reply to this email to confirm your availability. If you need clarification, you can contact the Jobmitra team.'\n          };break;\n        case 'technical_interview': {\n          const technicalDay = escapeHtml(formatDate(get('technicalDate')) || '[Interview Date]');\n          const technicalWeekday = escapeHtml(formatWeekday(get('technicalDate')) || '[Day]');\n          const technicalClock = escapeHtml(formatTime(get('technicalTime')) || '[Time]');\n          const technicalMeetingUrl = getMeetingUrl('technicalMeetingLink');\n          const technicalMeetingId = get('technicalMeetingId');\n          const technicalPasscode = get('technicalPasscode');\n          const technicalLinkCell = technicalMeetingUrl\n            ? `<a href=\"${escapeHtml(technicalMeetingUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#dd0000;text-decoration:underline;font-weight:bold;overflow-wrap:anywhere;word-break:break-word;\">Join technical interview</a><br><a href=\"${escapeHtml(technicalMeetingUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#44515e;font-size:11px;font-weight:normal;text-decoration:underline;overflow-wrap:anywhere;word-break:break-all;\">${escapeHtml(technicalMeetingUrl)}</a>`\n            : '<span style=\"color:#687583;font-weight:normal;\">Use the Meeting ID below to join</span>';\n          content = {\n            subject:`Technical Interview Invitation | ${get('jobPosition')||'[Position]'}`,\n            eyebrow:'TECHNICAL INTERVIEW INVITATION',\n            title:'Your technical interview is scheduled',\n            sub:'Please join the interview call at the scheduled time.',\n            intro:`Following your initial interview, the hiring team has scheduled your technical interview for the <strong>${role}</strong> position.`,\n            statusLabel:'Technical Interview Scheduled',\n            statusSubline:'Online technical round · Schedule confirmed by the hiring team',\n            details:[\n              {label:'Position',value:role},\n              {label:'Interview date',value:technicalDay},\n              {label:'Day',value:technicalWeekday},\n              {label:'Interview time',value:technicalClock},\n              ...(technicalMeetingUrl ? [{label:'Interview meeting link',value:technicalLinkCell}] : []),\n              ...(technicalMeetingId ? [{label:'Meeting ID',value:escapeHtml(technicalMeetingId)}] : []),\n              ...(technicalPasscode ? [{label:'Passcode',value:escapeHtml(technicalPasscode)}] : [])\n            ],\n            body:'Please join the technical interview call on time using the details above. We recommend joining a few minutes early, checking your microphone and internet connection, and keeping your updated resume ready.',\n            next:'Please reply to confirm your availability. If you have any difficulty joining the meeting, contact the Jobmitra team.'\n          };break;\n        }\n        case 'f2f_company': {\n          const f2fDate = escapeHtml(formatNumericDate(get('f2fDate')) || '[Date]');\n          const f2fDay = escapeHtml(formatWeekday(get('f2fDate')) || '[Day]');\n          const f2fTime = escapeHtml(formatTime(get('f2fTime')) || '[Time]');\n          const f2fVenue = escapeHtml(get('f2fVenue') || '[Full interview venue address]').replace(/\\n/g,'<br>');\n          content = {\n            recipient:'company',\n            subject:`Face-to-Face Interview Confirmation | ${get('candidateName')||'[Candidate Name]'} | ${get('jobPosition')||'[Position]'}`,\n            eyebrow:'INTERVIEW CONFIRMATION',title:'Face-to-face interview confirmed',sub:'Confirmed interview details for your hiring team.',\n            intro:`I am pleased to confirm that <strong>${name}</strong> is scheduled for a face-to-face interview for the <strong>${role}</strong> position on <strong>${f2fDay}, ${f2fDate}</strong>.`,\n            statusLabel:'F2F Interview Confirmed',statusSubline:'Schedule details for the hiring company',\n            details:[\n              {label:'Candidate',value:name},\n              {label:'Date',value:f2fDate},\n              {label:'Day',value:f2fDay},\n              {label:'Time',value:f2fTime},\n              {label:'Position',value:role},\n              {label:'Format',value:'Face-to-Face (F2F)'},\n              {label:'Interview location',value:f2fVenue}\n            ],\n            body:'Please forward the confirmed interview slot to your internal interviewing panel. If any last-minute adjustments are required, kindly let us know.',\n            next:'Thank you for your coordination.'\n          };break;\n        }\n        case 'round1_completed':\n          content = {subject:`Round 1 Interview Update | ${get('jobPosition')||'[Position]'} — ${get('companyName')||'[Company]'}`,\n            eyebrow:'INTERVIEW STATUS',title:'Round 1 interview completed',sub:'We will keep you informed of the next update.',\n            intro:`Thank you for attending the first interview round for the <strong>${role}</strong> role with <strong>${company}</strong>.`,statusLabel:'Round 1 Completed · Feedback Pending',details:basic,\n            body:'Your interview has been completed, and the hiring team’s feedback is currently awaited. This update does not indicate a selection or rejection decision.',\n            next:'We will contact you once the employer shares the next steps. Thank you for your patience.'};break;\n        case 'round1_cleared':\n          content = {subject:`Congratulations! Round 1 Cleared | ${get('jobPosition')||'[Position]'} — ${get('companyName')||'[Company]'}`,\n            eyebrow:'INTERVIEW PROGRESS',title:'Congratulations on clearing Round 1!',sub:'You have moved one step closer to your next opportunity.',\n            intro:`We are pleased to inform you that you have <strong>successfully cleared the first interview round</strong> for the <strong>${role}</strong> position with <strong>${company}</strong>.`,statusLabel:'Round 1 Cleared',\n            details:[...basic,...(confirmedNext?[{label:'Next interview',value:confirmedNext}]:[])],\n            body:confirmedNext?`Your next interview is confirmed for <strong>${confirmedNext}</strong>. Please prepare accordingly. Our team will share any additional interview instructions.`:'The next round’s schedule and format will be shared with you once confirmed by the hiring company.',\n            next:'Thank you for your time and effort so far. We wish you the best for your next round.'};break;\n        case 'round2_completed':\n          content = {subject:`Round 2 Interview Update | ${get('jobPosition')||'[Position]'} — ${get('companyName')||'[Company]'}`,\n            eyebrow:'INTERVIEW STATUS',title:'Round 2 interview completed',sub:'Your interview feedback is being awaited.',\n            intro:`Thank you for attending the second interview round for the <strong>${role}</strong> position with <strong>${company}</strong>.`,statusLabel:'Round 2 Completed · Feedback Pending',details:basic,\n            body:'Your second interview is now complete. The hiring team is reviewing the outcome, and no final decision has been communicated at this stage.',\n            next:'We will share a confirmed update as soon as we hear from the company. We appreciate your patience.'};break;\n        case 'round2_cleared':\n          content = {subject:`Congratulations! Round 2 Cleared | ${get('jobPosition')||'[Position]'} — ${get('companyName')||'[Company]'}`,\n            eyebrow:'INTERVIEW PROGRESS',title:'Congratulations on clearing Round 2!',sub:'A positive step forward in your hiring process.',\n            intro:`We are pleased to confirm that you have <strong>successfully cleared the second interview round</strong> for the <strong>${role}</strong> opportunity at <strong>${company}</strong>.`,statusLabel:'Round 2 Cleared',\n            details:[...basic,...(confirmedNext?[{label:'Next interview',value:confirmedNext}]:[])],\n            body:confirmedNext?`Your next discussion is confirmed for <strong>${confirmedNext}</strong>. We will share any further instructions as required.`:'We are coordinating with the hiring team regarding the next stage. Any further assessment or final decision will be communicated once confirmed.',\n            next:'We appreciate the effort you have put into this process and wish you continued success.'};break;\n        case 'final_completed': {\n          // Retain the legacy dropdown value for compatibility; this stage now sends a scheduled invitation.\n          const finalDate = escapeHtml(formatDate(get('finalDate')) || '[Interview Date]');\n          const finalTime = formatTime(get('finalTime')) ? `${escapeHtml(formatTime(get('finalTime')))} IST` : '[Interview Time]';\n          const finalUrl = getMeetingUrl('finalMeetingLink');\n          const meetingId = get('finalMeetingId');\n          const passcode = get('finalPasscode');\n          const finalMeetingLink = finalUrl\n            ? `<a href=\"${escapeHtml(finalUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#dd0000;font-weight:bold;text-decoration:underline;\">Join Interview</a><br><a href=\"${escapeHtml(finalUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#44515e;font-size:11px;text-decoration:underline;overflow-wrap:anywhere;word-break:break-all;\">${escapeHtml(finalUrl)}</a>`\n            : '';\n          const customBodyHtml=companyInterviewReadinessHtml('Online');\n          content = {\n            subject:'Final Interview Invitation | Senior Management Round | Jobmitra',\n            eyebrow:'FINAL INTERVIEW INVITATION',\n            title:'Your Final Interview with Top Management Confirmed',\n            sub:'Your final-stage interview has been scheduled.',\n            intro:'We are pleased to inform you that your <strong>Final Interview with the Senior Management Team</strong> has been scheduled.<br><br>Please review the interview details and preparation checklist below carefully.',\n            statusLabel:'Final Interview Details',\n            details:[\n              {label:'Interview Date',value:finalDate},\n              {label:'Interview Time',value:finalTime},\n              ...(finalMeetingLink ? [{label:'Meeting Link',value:finalMeetingLink}] : []),\n              ...(meetingId ? [{label:'Meeting ID',value:escapeHtml(meetingId)}] : []),\n              ...(passcode ? [{label:'Passcode',value:escapeHtml(passcode)}] : [])\n            ],\n            customBodyHtml,\n            hideReview:true,\n            hideFooter:true\n          };break;\n        }\n        case 'selected':\n          content = {subject:`Congratulations on Your Selection! | ${get('jobPosition')||'[Position]'} — ${get('companyName')||'[Company]'}`,\n            eyebrow:'SELECTION CONFIRMATION',title:'Congratulations on your selection!',sub:'A new chapter in your career begins here.',\n            intro:`We are delighted to inform you that <strong>${company}</strong> has confirmed your selection for the position of <strong>${role}</strong>. Congratulations on this achievement!`,statusLabel:'Selection Confirmed',statusSubline:'Recruitment Facilitated by Jobmitra',\n            details:[...basic,...(confirmedJoining?[{label:'Confirmed joining date',value:escapeHtml(confirmedJoining)}]:[])],\n            body:'The Jobmitra team will coordinate the next steps with you. Please look out for formal offer, documentation and joining instructions from the hiring company or through our team. Any terms of employment should be verified against the employer’s official offer.',\n            next:'It has been a pleasure supporting your hiring journey. We wish you the very best as you move forward.'};break;\n        case 'offer_received':\n          content = {subject:`Offer Update | ${get('jobPosition')||'[Position]'} — ${get('companyName')||'[Company]'}`,\n            eyebrow:'OFFER UPDATE',title:'Congratulations on your offer!',sub:'Please review your offer details carefully.',\n            intro:`Congratulations! An offer for the <strong>${role}</strong> position with <strong>${company}</strong> has been shared as part of your hiring process.`,statusLabel:'Offer Shared / Received',\n            details:[...basic,...(confirmedJoining?[{label:'Confirmed joining date',value:escapeHtml(confirmedJoining)}]:[])],\n            body:'Please review the employer’s official offer carefully, including the role, compensation, documents required, location and joining terms. Confirm acceptance or raise any questions using the instructions provided by the hiring company.',\n            next:'Jobmitra is here to assist you with recruitment coordination and any clarification needed before joining.'};break;\n        case 'joined':\n          content = {subject:`Congratulations on Your New Beginning! | ${get('companyName')||'[Company]'}`,\n            eyebrow:'NEW BEGINNING',title:'Wishing you success in your new role!',sub:'Congratulations on reaching this career milestone.',\n            intro:`Congratulations on starting your new professional journey as <strong>${role}</strong> with <strong>${company}</strong>!`,statusLabel:'Joined Successfully',\n            details:[...basic,...(confirmedJoining?[{label:'Date of joining',value:escapeHtml(confirmedJoining)}]:[])],\n            body:'We are glad to have supported you through the recruitment process. We hope your new role brings meaningful opportunities, learning and growth.',\n            next:'Thank you for trusting Jobmitra during your job search. Wishing you a fulfilling and successful career ahead.'};break;\n        case 'not_selected':\n          content = {subject:`Application Update | ${get('jobPosition')||'[Position]'} | Jobmitra`,\n            eyebrow:'APPLICATION UPDATE',title:'Thank you for your time and interest',sub:'An update on your recent application.',\n            intro:`Thank you for the interest and effort you have shown during the recruitment process for the <strong>${role}</strong> opportunity.`,statusLabel:'Not Selected for This Role',details:[{label:'Position',value:role}],\n            body:'After reviewing the requirements for this particular role, we regret to inform you that your application will not be progressing further at this time. This decision relates only to the current opportunity.',\n            next:'We appreciate the time you invested and would be glad to consider your profile for future openings that match your skills and preferences. With your permission, the Jobmitra team may contact you when suitable opportunities become available. Thank you for staying connected with us.',hideReview:true};break;\n        default: throw new Error('Unknown email status');\n      }\n      const companyInvitation=['interview_scheduled','technical_interview','custom_round'].includes(status);\n      const confirmedNextInterview=['round1_cleared','round2_cleared'].includes(status) && Boolean(confirmedNext);\n      if(companyInvitation || confirmedNextInterview){\n        // The technical round uses a dedicated online invitation; generic/custom rounds honor their selected mode.\n        const invitationMode=status==='technical_interview'?'Online':get('interviewMode')||'Online';\n        content.readinessHtml=companyInterviewReadinessHtml(invitationMode);\n      }\n      // Final/senior-management round already renders the shared checklist as its complete body.\n      const companyFacing = ['f2f_company','candidate_submission'].includes(status);\n      const companyDisclosed = ['selected','offer_received','joined'].includes(status);\n      if(!companyFacing && !companyDisclosed){\n        const internal=String(get('companyName')||'').trim();\n        const hiddenName=escapeHtml(internal);\n        const redact=text=>{\n          let out=String(text||'');\n          if(internal){out=out.split(internal).join('the hiring organization');out=out.split(hiddenName).join('the hiring organization');}\n          out=out.replace(/\\s+[—–-]\\s+\\[Company\\]/g,'').replace(/\\s+[—–-]\\s+the hiring organization/g,'');\n          return out;\n        };\n        for(const k of ['subject','intro','body','next','sub','statusSubline'])if(content[k])content[k]=redact(content[k]);\n        content.details=(content.details||[]).filter(row=>!(/company|organization/i.test(row.label))).map(row=>({...row,value:redact(row.value)}));\n      }else if(companyDisclosed){\n        // Confirmation, offers and joining may contain the employer's verified name.\n        if(get('companyName'))content.details=(content.details||[]).some(x=>x.label==='Hiring company')?content.details:[...content.details,verifiedCompanyDetail];\n      }\n      return content;\n    }\n    function detailRow(label,value,index) {\n      const bg = index%2 ? '#ffffff' : '#fff8f8';\n      return `<tr><td style=\"font-family:Arial,sans-serif;font-size:12px;color:#687583;padding:11px 16px;width:35%;border-bottom:1px solid #edf0f2;background:${bg};vertical-align:top;\">${escapeHtml(label)}</td><td style=\"font-family:Arial,sans-serif;font-size:13px;font-weight:bold;color:#22303b;padding:11px 16px;border-bottom:1px solid #edf0f2;background:${bg};vertical-align:top;\">${value}</td></tr>`;\n    }\n    function makeEmailHTML(data,content) {\n      const sender = val('recruiterName','Team Jobmitra');\n      const phone = get('recruiterPhone')?`<span style=\"font-size:12px;color:#687583\">Contact: ${escapeHtml(get('recruiterPhone'))}</span><br>`:'';\n      const greeting = content.greeting || (content.recipient==='company' ? `Hi <strong>${data.company}</strong>,` : `Dear <strong>${data.name}</strong>,`);\n      const customNote = get('personalNote');\n      const noteHtml = customNote ? `<tr><td style=\"padding:1px 37px 18px 37px;\"><table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" role=\"presentation\" style=\"border-collapse:collapse;\"><tr><td style=\"background-color:#f7f8fa;border-left:3px solid #dd0000;padding:13px 15px;font-family:Arial,sans-serif;font-size:13px;line-height:1.75;color:#4b5968;\"><strong style=\"color:#263441;\">Additional note:</strong><br>${escapeHtml(customNote).replace(/\\n/g,'<br>')}</td></tr></table></td></tr>`:'';\n      const reviewHtml = content.recipient==='company' || content.hideReview ? '' : `<tr><td style=\"padding:8px 37px 28px 37px;\"><table width=\"100%\" role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" style=\"border-collapse:collapse;\"><tr><td style=\"padding:23px 23px 25px;background-color:#fff9f9;border:1px solid #f0dada;text-align:center;\"><p style=\"font-family:Arial,sans-serif;font-size:15px;line-height:1.5;color:#263441;margin:0 0 7px;font-weight:bold;\">We'd value your feedback</p><p style=\"font-family:Arial,sans-serif;font-size:12px;line-height:1.8;color:#606b78;margin:0 0 19px;\">If you would like, share an honest review of your Jobmitra experience. Your feedback is entirely optional and does not affect your application.</p><a href=\"${REVIEW_URL}\" target=\"_blank\" style=\"font-family:Arial,sans-serif;background-color:#dd0000;color:#ffffff;text-decoration:none;padding:12px 20px;display:inline-block;font-size:13px;font-weight:bold;border-radius:5px;\">★ &nbsp; Write a Google Review</a></td></tr></table></td></tr>`;\n      const stageBodyHtml = content.customBodyHtml || `<tr><td style=\"padding:0 37px;\"><p style=\"font-family:Arial,sans-serif;font-size:13px;color:#44515e;line-height:1.85;margin:0 0 14px;\">${content.body}</p><p style=\"font-family:Arial,sans-serif;font-size:13px;color:#44515e;line-height:1.85;margin:0 0 25px;\">${content.next}</p></td></tr>`;\n      const footerInfo = content.footerText || (content.recipient==='company'\n        ? 'This message confirms interview coordination details communicated by Jobmitra. Please notify us of changes to the schedule or interview location.'\n        : 'This message is from Jobmitra, a recruitment facilitator. Hiring decisions, employment terms and official offers are determined by the hiring company. If you have any questions, please reply to this email.');\n      const footerHtml = content.hideFooter ? '' : `<tr><td bgcolor=\"#f7f8fa\" style=\"background-color:#f7f8fa;padding:19px 37px;border-top:1px solid #e9ecef;\"><p style=\"font-family:Arial,sans-serif;color:#7a858f;font-size:11px;line-height:1.7;margin:0;\">${footerInfo}</p><p style=\"font-family:Arial,sans-serif;color:#9aa4ac;font-size:10px;margin:10px 0 0;\">Jobmitra · Your online job friend · Indore, Madhya Pradesh</p></td></tr>`;\n      return `<table width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" role=\"presentation\" bgcolor=\"#f4f5f7\" style=\"margin:0;background-color:#f4f5f7;border-collapse:collapse;width:100%;font-family:Arial,Helvetica,sans-serif;\"><tr><td align=\"center\" style=\"padding:26px 13px;\"><table width=\"600\" cellspacing=\"0\" cellpadding=\"0\" role=\"presentation\" bgcolor=\"#ffffff\" style=\"border-collapse:collapse;background-color:#ffffff;width:100%;max-width:600px;border:1px solid #e6e9ed;\">\n      <tr><td bgcolor=\"#ffffff\" align=\"center\" style=\"background-color:#ffffff;padding:25px 35px 22px;border-bottom:1px solid #eceff3;text-align:center;\"><img src=\"${LOGO_DATA_URL}\" alt=\"Jobmitra.com — Your online job friend\" width=\"290\" style=\"display:block;width:290px;max-width:100%;height:auto;border:0;margin:0 auto;\"></td></tr>\n      <tr><td style=\"padding:33px 37px 0;\"><div style=\"font-family:Arial,sans-serif;color:#dd0000;font-size:10px;letter-spacing:1.9px;font-weight:bold;text-transform:uppercase;margin-bottom:10px;\">${escapeHtml(content.eyebrow)}</div><h1 style=\"font-family:Arial,sans-serif;margin:0 0 10px;font-size:26px;font-weight:bold;line-height:1.26;color:#1c2732;letter-spacing:-.5px;\">${escapeHtml(content.title)}</h1>${content.sub?`<p style=\"font-family:Arial,sans-serif;font-size:13px;color:#6b7682;line-height:1.7;margin:0 0 24px;\">${escapeHtml(content.sub)}</p>`:'<div style=\"height:20px\"></div>'}</td></tr>\n      <tr><td style=\"padding:0 37px;\"><p style=\"font-family:Arial,sans-serif;font-size:14px;color:#273440;line-height:1.7;margin:0 0 14px;\">${greeting}</p><p style=\"font-family:Arial,sans-serif;font-size:14px;color:#44515e;line-height:1.82;margin:0 0 24px;\">${content.intro}</p></td></tr>\n${content.hideStatusBox?'':`      <tr><td style=\"padding:0 37px 24px;\"><table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" role=\"presentation\" style=\"border-collapse:collapse;border:1px solid #e6eaee;border-bottom:2px solid #dd0000;\"><tr><td colspan=\"2\" bgcolor=\"#dd0000\" style=\"background-color:#dd0000;color:#ffffff;font-family:Arial,sans-serif;padding:14px 16px 15px;\"><div style=\"font-family:Arial,sans-serif;font-size:12px;line-height:1.4;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#ffffff;\">${escapeHtml(content.statusLabel)}</div>${content.statusSubline ? `<div style=\"font-family:Arial,sans-serif;font-size:11px;line-height:1.5;font-weight:normal;letter-spacing:.1px;color:#ffffff;margin-top:4px;\">${escapeHtml(content.statusSubline)}</div>` : ''}</td></tr>${content.details.map((r,i)=>detailRow(r.label,r.value,i)).join('')}</table></td></tr>`}\n      ${stageBodyHtml}\n      ${content.readinessHtml||''}\n      ${noteHtml}\n      <tr><td style=\"padding:0 37px 26px;\"><p style=\"font-family:Arial,sans-serif;font-size:13px;color:#44515e;line-height:1.85;margin:0;\">Warm regards,<br><strong style=\"color:#263440;\">${sender}</strong><br><span style=\"color:#dd0000;font-weight:bold;\">Jobmitra Recruitment Team</span><br>${phone}<a href=\"${WEBSITE_URL}\" target=\"_blank\" style=\"font-family:Arial,sans-serif;font-size:12px;color:#dd0000;text-decoration:none;\">www.jobmitra.com</a></p></td></tr>\n      ${reviewHtml}\n      ${footerHtml}\n      </table></td></tr></table>`;\n    }\n    function updateStageFields() {\n      const s=get('candidateStatus');\n      $('submissionFields').classList.toggle('hidden',s!=='candidate_submission');\n      $('otherStageFieldsHeading').classList.toggle('hidden',s==='candidate_submission');\n      $('candidateName').closest('.field').classList.toggle('hidden',s==='candidate_submission');\n      $('interviewScheduleFields').classList.toggle('hidden',!['interview_scheduled','jobmitra_screening','custom_round'].includes(s));\n      $('roundFields').classList.toggle('hidden',s!=='custom_round');\n      $('candidatePrivacyNotice').classList.toggle('hidden',['candidate_submission','f2f_company','selected','offer_received','joined'].includes(s));\n      $('technicalInterviewFields').classList.toggle('hidden',s!=='technical_interview');\n      $('finalInterviewFields').classList.toggle('hidden',s!=='final_completed');\n      $('jobPositionField').classList.remove('hidden');\n      $('faceToFaceFields').classList.toggle('hidden',s!=='f2f_company');\n      $('jobLocationField').classList.toggle('hidden',s!=='f2f_company'&&s!=='selected'&&s!=='offer_received'&&s!=='joined');\n      $('companyNameField').classList.toggle('hidden',!['candidate_submission','f2f_company','selected','offer_received','joined'].includes(s));\n      $('nextScheduleFields').classList.toggle('hidden',!STAGES_WITH_NEXT.includes(s));\n      $('joiningFields').classList.toggle('hidden',!STAGES_WITH_JOINING.includes(s));\n      $('statusHint').textContent=statusHints[s] || '';\n      refreshRecipient();\n    }\n    function build() {\n      const data={name:val('candidateName','[Candidate Name]'),role:val('jobPosition','[Position]'),company:val('companyName','[Company]'),location:val('jobLocation','[Location]'),status:get('candidateStatus')};\n      const content=stageContent(data);\n      const stage=get('candidateStatus');\n      if(currentSubjectStage!==stage){currentSubjectStage=stage;customizedSubject='';}\n      if(document.activeElement!==$('emailSubject'))$('emailSubject').value=customizedSubject||content.subject;\n      $('emailBody').innerHTML=makeEmailHTML(data,content);\n      const complete=getRequiredFields().every(x=>get(x)) && (get('candidateStatus')!=='final_completed' || !!(get('finalMeetingLink') || get('finalMeetingId'))) && (stage!=='candidate_submission' || submissionRows.every(r=>r.name.trim()&&Number.isInteger(r.serial)&&r.serial>0));\n      $('modeFlag').textContent=isDemo?'Demo details · replace before sending':(complete && recipientValid(get('recipientEmail'))?'Ready to copy · recipient verified':complete?'Content ready · enter recipient before sending':'Preview mode · fill required details');\n      updateStageFields();\n    }\n    function showToast(message,error=false) {\n      clearTimeout(toastTimeout);\n      const toast=$('toast');toast.textContent=message;toast.style.background=error?'#dd0000':'#172735';toast.classList.add('show');\n      toastTimeout=setTimeout(()=>toast.classList.remove('show'),4400);\n    }\n    function validate() {\n      let first;\n      let errorMessage = '';\n      const s = get('candidateStatus');\n      const requiredFields = getRequiredFields();\n      if(['interview_scheduled','jobmitra_screening','custom_round'].includes(s))requiredFields.push('interviewDate','interviewTime');\n      for(const id of [...new Set([...REQUIRED,...F2F_REQUIRED,...TECHNICAL_REQUIRED,...FINAL_REQUIRED])]) $(id).classList.remove('invalid');\n      for(const id of requiredFields){\n        const el=$(id);\n        el.classList.toggle('invalid',!get(id));\n        if(!get(id) && !first) first=el;\n      }\n      $('interviewMeetingLink').classList.remove('invalid');\n      $('technicalMeetingLink').classList.remove('invalid');\n      $('finalMeetingLink').classList.remove('invalid');\n      const linkField = s==='technical_interview' ? 'technicalMeetingLink' : (s==='final_completed' ? 'finalMeetingLink' : (['interview_scheduled','jobmitra_screening','custom_round'].includes(s) ? 'interviewMeetingLink' : ''));\n      if(linkField && get(linkField) && !getMeetingUrl(linkField)) {\n        $(linkField).classList.add('invalid');\n        if(!first) {\n          first=$(linkField);\n          errorMessage='Please enter a valid meeting URL beginning with https:// or http://.';\n        }\n      }\n      if(s==='technical_interview' && !get('technicalMeetingLink') && !get('technicalMeetingId')) {\n        $('technicalMeetingLink').classList.add('invalid');\n        $('technicalMeetingId').classList.add('invalid');\n        if(!first) {\n          first=$('technicalMeetingLink');\n          errorMessage='Enter either the technical interview meeting link or Meeting ID.';\n        }\n      } else {\n        $('technicalMeetingId').classList.remove('invalid');\n      }\n      if(s==='final_completed' && !get('finalMeetingLink') && !get('finalMeetingId')) {\n        $('finalMeetingLink').classList.add('invalid');\n        $('finalMeetingId').classList.add('invalid');\n        if(!first) {\n          first=$('finalMeetingLink');\n          errorMessage='Enter either the final interview meeting link or Meeting ID.';\n        }\n      } else {\n        $('finalMeetingId').classList.remove('invalid');\n      }\n      if(!first && s==='candidate_submission' && !validateSubmission())return false;\n      if(!first && !['selected','offer_received','joined','f2f_company','candidate_submission'].includes(s)){\n        const company=get('companyName').trim();\n        if(company && [get('personalNote'),$('emailSubject').value].some(value=>value.toLowerCase().includes(company.toLowerCase()))){\n          first=$('emailSubject');errorMessage='Company confidentiality: remove the hiring company name from the subject or additional note before copying.';\n        }\n      }\n      if(!first && !$('emailSubject').value.trim()){first=$('emailSubject');errorMessage='Enter an email subject before copying.';}\n      if(first) {\n        first.focus();\n        showToast(errorMessage || (s==='f2f_company'\n          ? 'Please fill candidate name, position, company, interview date, time and venue.'\n          : s==='technical_interview'\n            ? 'Please enter candidate name, position, technical interview date and time.'\n            : s==='final_completed'\n              ? 'Please enter candidate name, final interview date and time.'\n              : 'Please fill candidate name, position, company and location before copying.'),true);\n        return false;\n      }\n      return true;\n    }\n\n    function legacyRichCopy(node) {\n      const selection=window.getSelection();const oldRanges=[];\n      for(let i=0;i<selection.rangeCount;i++)oldRanges.push(selection.getRangeAt(i));\n      const range=document.createRange();range.selectNode(node);\n      selection.removeAllRanges();selection.addRange(range);\n      let success=false;\n      try{success=document.execCommand('copy');}catch(e){success=false;}\n      selection.removeAllRanges();for(const r of oldRanges)selection.addRange(r);\n      return success;\n    }\n    async function copyEmail() {\n      if(!validate())return;\n      const table=$('emailBody').firstElementChild;\n      // Selecting the full table preserves the wrapper, background and all inline styles in Gmail's rich HTML paste.\n      if(legacyRichCopy(table)){showToast('Formatted email copied! Open Gmail Compose and paste it into the message body.');return;}\n      try{\n        if(!navigator.clipboard?.write || !window.ClipboardItem)throw new Error('Rich clipboard API unavailable');\n        await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([table.outerHTML],{type:'text/html'}),'text/plain':new Blob([$('emailBody').innerText],{type:'text/plain'})})]);\n        showToast('Formatted email copied! Paste it into the Gmail message body.');\n      }catch(e){showToast('Could not copy automatically. Select the rendered email in the preview and copy with Ctrl+C.',true);}\n    }\n    async function copySubject() {\n      if(!validate())return;\n      const value=$('emailSubject').value;\n      try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);showToast('Subject copied. Paste it into the Gmail subject field.');return;}}catch(e){}\n      const area=document.createElement('textarea');area.value=value;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();\n      const copied=document.execCommand('copy');area.remove();showToast(copied?'Subject copied. Paste it into the Gmail subject field.':'Subject copy failed; select and copy the subject text manually.',!copied);\n    }\n    function downloadEmail() {\n      if(!validate())return;\n      const title=$('emailSubject').value;\n      const content='<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>'+escapeHtml(title)+'</title></head><body style=\"margin:0;padding:0;background:#f4f5f7;\">'+$('emailBody').innerHTML+'</body></html>';\n      const blob=new Blob([content],{type:'text/html;charset=utf-8'});\n      const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='Jobmitra_Email_'+get('candidateStatus')+'.html';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),4000);\n      showToast('Email HTML downloaded. Open it in a browser or use it for future integration.');\n    }\n    const allFieldIds=['roundName','roundInterviewer','candidateName','jobPosition','companyName','jobLocation','candidateStatus','interviewDate','interviewTime','interviewMode','interviewMeetingLink','interviewMeetingId','interviewPasscode','technicalDate','technicalTime','technicalMeetingLink','technicalMeetingId','technicalPasscode','finalDate','finalTime','finalMeetingLink','finalMeetingId','finalPasscode','f2fDate','f2fTime','f2fVenue','nextDate','nextTime','joiningDate','recruiterName','recruiterPhone','personalNote'];\n    function resetFields() {\n      for(const id of allFieldIds){const el=$(id);el.value='';el.classList.remove('invalid');}\n      resetSubmissionEditor();clearRecipientState();\n      $('candidateStatus').value='selected';customizedSubject='';currentSubjectStage='';isDemo=false;build();showToast('Fields cleared. Ready for the next candidate.');\n    }\n    function loadDemo() {\n      const values={candidateName:'Rahul Sharma',jobPosition:'Python Developer',companyName:'ABC Technologies',jobLocation:'Indore, Madhya Pradesh',candidateStatus:'selected',recruiterName:'Team Jobmitra'};\n      resetFields();for(const [k,v] of Object.entries(values))$(k).value=v;\n      recipientDefaults.candidate='demo.candidate@example.com';recipientDefaults.company='demo.company@example.com';recipientOrigins.candidate='candidate';recipientOrigins.company='company';recipientKindActive=null;\n      isDemo=true;build();showToast('Demo details loaded. This is fictional sample data—replace it before sending.');\n    }\n    for(const id of allFieldIds){\n      $(id).addEventListener('input',()=>{if(id==='candidateName')invalidateRecipientOnNameChange('candidate');if(id==='companyName')invalidateRecipientOnNameChange('company');if(id!=='candidateStatus') $(id).classList.remove('invalid');if(isDemo && !REQUIRED.some(k=>get(k)===DEMO_REQUIRED[k]))isDemo=false;build();});\n      $(id).addEventListener('change',()=>{if(isDemo && !REQUIRED.some(k=>get(k)===DEMO_REQUIRED[k]))isDemo=false;build();});\n    }\n    $('submissionAdd').addEventListener('click',()=>{\n      if(submissionRows.length>=50){showToast('Use up to 50 candidate rows in one draft.',true);return;}\n      const last=submissionRows.at(-1);\n      submissionRows.push({id:submissionSeq++,serial:(last?.serial||0)+1,name:'',experience:'',currentCTC:'',expectedCTC:'',notice:''});\n      renderSubmissionEditor();build();\n    });\n    $('submissionStart').addEventListener('input',()=>{\n      const first=Number(get('submissionStart'));\n      if(Number.isInteger(first)&&first>0&&first<=99999){submissionRows.forEach((r,i)=>r.serial=first+i);renderSubmissionEditor();}\n      build();\n    });\n    $('submissionRows').addEventListener('input',e=>{\n      const field=e.target?.dataset?.subField;\n      if(!['serial','name','experience','currentCTC','expectedCTC','notice'].includes(field))return;\n      const c=submissionRows.find(x=>x.id===Number(e.target.dataset.subId));if(!c)return;\n      c[field]=field==='serial'?Number(e.target.value):e.target.value;\n      e.target.classList.remove('invalid');isDemo=false;build();\n    });\n    $('submissionRows').addEventListener('click',e=>{\n      const btn=e.target.closest('[data-remove-submission]');\n      if(!btn||submissionRows.length===1)return;\n      submissionRows=submissionRows.filter(x=>x.id!==Number(btn.dataset.removeSubmission));\n      renderSubmissionEditor();build();\n    });\n    $('notSelectedQuick').addEventListener('click',()=>{$('candidateStatus').value='not_selected';customizedSubject='';currentSubjectStage='';build();$('candidateStatus').focus();});\n    $('recipientEmail').addEventListener('input',()=>{const kind=recipientKind(get('candidateStatus'));recipientEdited[kind]=$('recipientEmail').value; $('recipientEmail').classList.remove('invalid');refreshRecipient();build();});\n    $('companyContactSelect').addEventListener('change',()=>{const v=$('companyContactSelect').value;if(v){$('recipientEmail').value=v;recipientEdited.company=v;refreshRecipient();build();}});\n    $('copyRecipientBtn').addEventListener('click',copyRecipient);\n    $('sampleBtn').addEventListener('click',loadDemo);\n    $('clearBtn').addEventListener('click',resetFields);\n    $('copyEmailBtn').addEventListener('click',copyEmail);\n    $('copySubjectBtn').addEventListener('click',copySubject);\n    $('resetSubjectBtn').addEventListener('click',()=>{customizedSubject='';$('emailSubject').value=stageContent({name:val('candidateName','[Candidate Name]'),role:val('jobPosition','[Position]'),company:val('companyName','[Company]'),location:val('jobLocation','[Location]'),status:get('candidateStatus')}).subject;showToast('Default subject restored.');});\n    $('emailSubject').addEventListener('input',()=>{customizedSubject=$('emailSubject').value.trim();});\n    $('downloadBtn').addEventListener('click',downloadEmail);\n    build();\n  })();\n  \n  \n  <\/script>\n</body>\n</html>\n";
installEmailWorkspace(EMAIL_STUDIO_DOCUMENT);
installContextualEmail(native,EMAIL_STUDIO_DOCUMENT,pipelineEmailContext);
}
